sql.if:
AND EXISTS (
    SELECT 1
    FROM biz_onboarding_application channel_filter
    WHERE channel_filter.tenant_id = merchant.tenant_id
      AND channel_filter.merchant_id = merchant.id
      AND channel_filter.deleted = 0

      AND channel_filter.channel_code = #{query.channelCode}


      AND channel_filter.status IN

        #{applicationStatus}



      AND COALESCE(channel_filter.update_time, channel_filter.create_time) <= #{query.applicationUpdatedTo}

)

mapper.select:
SELECT 

WHERE merchant.tenant_id = #{tenantId}
  AND merchant.id = #{merchantId}
  AND merchant.deleted = 0

SELECT application.merchant_id, application.id AS application_id, application.application_no, application.channel_code, application.requirement_version, application.channel_config_version, application.kyc_version_id, application.status AS application_status, application.reporting_status, application.agreement_status, application.card_binding_status, application.reserve_account_status, application.channel_final_status, application.raw_channel_status, application.submitted_time, application.completed_time, application.create_time, pricing.id AS pricing_version_id, pricing.agent_id AS pricing_agent_id, pricing.parent_pricing_version_id, pricing.version_no AS pricing_version_no, pricing.channel_code AS pricing_channel_code, pricing.product_code AS pricing_product_code, pricing.currency AS pricing_currency, pricing.pricing_rules_json, pricing.effective_time AS pricing_effective_time, pricing.expires_time AS pricing_expires_time, pricing.status AS pricing_status FROM biz_onboarding_application application LEFT JOIN biz_kyc_version kyc ON kyc.id = application.kyc_version_id AND kyc.tenant_id = application.tenant_id AND kyc.merchant_id = application.merchant_id AND kyc.deleted = 0 LEFT JOIN biz_agent_pricing_version pricing ON pricing.id = kyc.pricing_version_id AND pricing.tenant_id = application.tenant_id AND pricing.deleted = 0 WHERE application.tenant_id = #{tenantId} AND application.deleted = 0 AND application.merchant_id IN
#{merchantId}
AND NOT EXISTS ( SELECT 1 FROM biz_onboarding_application newer WHERE newer.tenant_id = application.tenant_id AND newer.merchant_id = application.merchant_id AND newer.channel_code = application.channel_code AND newer.deleted = 0 AND (newer.create_time > application.create_time OR (newer.create_time = application.create_time AND newer.id > application.id)) ) ORDER BY application.merchant_id, application.channel_code
